const BASE32 = '0123456789bcdefghjkmnpqrstuvwxyz';

function encodeGeohash(lat, lng, precision = 9) {
  let latRange = [-90, 90];
  let lngRange = [-180, 180];
  let isEven = true; // start by bisecting longitude
  let bit = 0;
  let ch = 0;
  let geohash = '';

  while (geohash.length < precision) {
    if (isEven) {
      const mid = (lngRange[0] + lngRange[1]) / 2;
      if (lng > mid) {
        ch = (ch << 1) + 1;
        lngRange[0] = mid;
      } else {
        ch = (ch << 1) + 0;
        lngRange[1] = mid;
      }
    } else {
      const mid = (latRange[0] + latRange[1]) / 2;
      if (lat > mid) {
        ch = (ch << 1) + 1;
        latRange[0] = mid;
      } else {
        ch = (ch << 1) + 0;
        latRange[1] = mid;
      }
    }

    isEven = !isEven;

    if (bit < 4) {
      bit++;
    } else {
      geohash += BASE32[ch];
      bit = 0;
      ch = 0;
    }
  }

  return geohash;
}

encodeGeohash(12.9352, 77.6146, 7); // "tdr1w4v"

